sp_widget.client_script:
api.controller = function($scope) {
  var c = this;

  // Compute relative time label ("1 day ago", "3 hours ago", etc.)
  c.timeAgo = function(dateStr) {
    if (!dateStr) return '';
    var now  = new Date();
    var then = new Date(dateStr.replace(' ', 'T'));
    var diff = Math.floor((now - then) / 1000); // seconds

    if (diff < 60)   return 'Just now';
    if (diff < 3600) return Math.floor(diff / 60) + ' min ago';
    if (diff < 86400) {
      var h = Math.floor(diff / 3600);
      return h + ' hour' + (h > 1 ? 's' : '') + ' ago';
    }
    var d = Math.floor(diff / 86400);
    return d + ' day' + (d > 1 ? 's' : '') + ' ago';
  };
};

sp_widget.css:
/* ─── Reset ───────────────────────────────────────────── */
.gna-wrapper *,
.gna-wrapper *::before,
.gna-wrapper *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  list-style: none;
}

/* ─── Outer wrapper ───────────────────────────────────── */
.gna-wrapper {
  font-family: 'Inter', 'Plus Jakarta Sans', 'Segoe UI', sans-serif;
  background: #ffffff;
  width: calc(100% + 30px);
  margin-left: -15px;
  margin-right: -15px;
  padding: 72px 0 80px;
  border-top: 1px solid #ebebeb;
}

/* ─── Inner: two columns ──────────────────────────────── */
.gna-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 60px;
  display: grid;
  grid-template-columns: 1fr 380px;
  align-items: center;
  gap: 0 60px;
}

/* ─── LEFT column ─────────────────────────────────────── */
.gna-left {
  display: flex;
  flex-direction: column;
  gap: 0;
}

.gna-eyebrow {
  font-size: 13px;
  font-weight: 500;
  color: #5443ad;
  letter-spacing: 0.01em;
  margin-bottom: 16px;
}

.gna-heading {
  font-size: 18px;
  font-weight: 400;
  line-height: 1.35;
  color: #111827;
  margin-bottom: 36px;
}

/* ─── Announcement list ───────────────────────────────── */
.gna-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.gna-item {
  display: flex;
  flex-direction: column;       /* stacked: name on top, time below */
  align-items: flex-start;
  gap: 6px;
  background: #f4f4f6;
  border-radius: 8px;
  padding: 16px 20px;
  border-left: 4px solid transparent;
  transition: border-color 0.18s ease;
  cursor: default;
}
.gna-item:first-child {
  border-left-color: #5443ad;   /* active/first item gets purple accent */
}
.gna-item:hover {
   border-left-color: #5443ad;   /* on hover any item gets accent */
  background: #f4f4f6;
}

.gna-item-name {
  font-size: 14px;
  font-weight: 400;
    color: #5443ad; 
  line-height: 1.4;
  flex: 1;
  min-width: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.gna-item-time {
  font-size: 13px;
  font-weight: 400;
    color: #6b7280; 
  flex-shrink: 0;
  white-space: nowrap;
}

/* ─── Empty state ─────────────────────────────────────── */
.gna-empty {
  font-size: 14px;
  color: #9ca3af;
  padding: 20px 0;
}

/* ─── RIGHT column: dot cluster ───────────────────────── */
.gna-right {
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: none;
  user-select: none;
}

.gna-dots {
  position: relative;
  width: 340px;
  height: 340px;
}

/* Each dot — absolutely positioned to form diagonal cluster */
.gna-dot {
  position: absolute;
  border-radius: 50%;
  display: block;
}

/* Row 1 — top right, darkest */
.gna-dot--r1c1 {
  width: 80px; height: 80px;
  background: rgba(108, 90, 190, 0.55);
  top: 0; right: 90px;
}
.gna-dot--r1c2 {
  width: 80px; height: 80px;
  background: rgba(108, 90, 190, 0.45);
  top: 0; right: 0;
}

/* Row 2 */
.gna-dot--r2c1 {
  width: 80px; height: 80px;
  background: rgba(108, 90, 190, 0.60);
  top: 90px; right: 180px;
}
.gna-dot--r2c2 {
  width: 80px; height: 80px;
  background: rgba(108, 90, 190, 0.50);
  top: 90px; right: 90px;
}

/* Row 3 */
.gna-dot--r3c1 {
  width: 80px; height: 80px;
  background: rgba(108, 90, 190, 0.35);
  top: 180px; right: 90px;
}
.gna-dot--r3c2 {
  width: 80px; height: 80px;
  background: rgba(108, 90, 190, 0.22);
  top: 180px; right: 0;
}

/* Row 4 — bottom left, lightest */
.gna-dot--r4c1 {
  width: 80px; height: 80px;
  background: rgba(108, 90, 190, 0.45);
  top: 260px; right: 180px;
}
.gna-dot--r4c2 {
  width: 80px; height: 80px;
  background: rgba(108, 90, 190, 0.18);
  top: 260px; right: 90px;
}

/* ─── Responsive ──────────────────────────────────────── */
@media (max-width: 1024px) {
  .gna-inner { padding: 0 40px; grid-template-columns: 1fr 280px; gap: 0 40px; }
  .gna-dots  { width: 260px; height: 260px; }
  .gna-dot   { width: 64px; height: 64px; }
  .gna-dot--r2c1 { right: 140px; }
  .gna-dot--r3c1 { top: 140px; }
  .gna-dot--r3c2 { top: 140px; }
  .gna-dot--r4c1 { top: 210px; right: 140px; }
  .gna-dot--r4c2 { top: 210px; }
}

@media (max-width: 820px) {
  .gna-inner   { grid-template-columns: 1fr; padding: 0 32px; }
  .gna-right   { display: none; }
  .gna-wrapper { padding: 48px 0 56px; }
}

@media (max-width: 520px) {
  .gna-inner   { padding: 0 20px; }
  .gna-heading { font-size: 20px; }
  .gna-item    { padding: 12px 16px; }
  .gna-item-name { font-size: 13px; }
}

sp_widget.script:
(function() {
  data.announcements = [];

  var gr = new GlideRecordSecure('x_enno_gatenow_grant_program');
  gr.addQuery('active', true);
  gr.addNotNullQuery('announcement');
  gr.orderByDesc('sys_updated_on');
  gr.setLimit(8);
  gr.query();

  while (gr.next()) {
    var updatedOn = gr.getValue('sys_updated_on'); // raw datetime string
    data.announcements.push({
      sys_id:       gr.getUniqueValue(),
      program_name: gr.getDisplayValue('program_name'),
      announcement: gr.getDisplayValue('announcement'),
      updated_on:   updatedOn
    });
  }
})();
